extends RefCounted

func setup() -> String:
	var shader := load("res://shaders/seance_toon.gdshader") as Shader
	if shader == null:
		return "FAIL: shader not found"
	var root := EditorInterface.get_edited_scene_root()
	if root == null:
		return "FAIL: no edited scene root"
	var sphere := root.get_node_or_null("MeshInstance3D")
	if sphere == null:
		return "FAIL: sphere not found"
	var mat := ShaderMaterial.new()
	mat.shader = shader
	# Seance palette: spectral cyan bands on dark ground
	mat.set_shader_parameter("highlight_color", Color(0.81, 0.94, 1.0, 1.0))
	mat.set_shader_parameter("mid1_color", Color(0.50, 0.70, 0.81, 1.0))
	mat.set_shader_parameter("mid2_color", Color(0.24, 0.37, 0.48, 1.0))
	mat.set_shader_parameter("shadow_color", Color(0.09, 0.13, 0.18, 1.0))
	mat.set_shader_parameter("light_direction", Vector3(0.5, 0.7, 0.3))
	mat.set_shader_parameter("smoothness", 0.05)
	sphere.set_material_override(mat)
	var err := EditorInterface.save_scene()
	if err != OK:
		return "SAVE_ERR: " + str(err)
	return "OK: toon material applied + scene saved"
